import codecs
events = []
class Mapping:
    def items(self):
        events.append('first')
        yield (1, 65)
        events.append('invalid')
        yield (2, [])
        raise AssertionError('consumed after unhashable target')
try:
    codecs.make_encoding_map(Mapping())
except TypeError as error:
    assert error.args == ("cannot use 'list' as a dict key (unhashable type: 'list')",)
else:
    assert False
print(events)
